import { API_ROUTES, routeUrl } from "@/app/api/routes";
import { requestJson } from "@/lib/api";

/**
 * Browser client for the in-app ACP client.
 *
 * These helpers talk to `/api/acp-client/*`, which spawns and drives external
 * ACP-compatible agents (Claude Agent, Codex, Gemini CLI, OpenCode, Goose, ...).
 * Connection ids and session ids are 20-digit numeric ids generated by the
 * backend — the connected agent's own session id is never exposed.
 */

export interface AcpImplementation {
  name: string;
  title?: string | null;
  version: string;
}

export interface AcpAuthMethod {
  id: string;
  name: string;
  description?: string;
  type?: "agent" | "terminal" | string;
  args?: string[];
  env?: Record<string, string>;
}

export interface AcpAgentCapabilities {
  loadSession?: boolean;
  promptCapabilities?: { image?: boolean; audio?: boolean; embeddedContext?: boolean };
  mcpCapabilities?: { http?: boolean; sse?: boolean };
  sessionCapabilities?: {
    resume?: unknown;
    close?: unknown;
    list?: unknown;
    delete?: unknown;
    additionalDirectories?: unknown;
  };
  [key: string]: unknown;
}

export interface AcpContentBlock {
  type?: string;
  text?: string;
  data?: string;
  mimeType?: string;
  uri?: string;
  name?: string;
  resource?: { uri?: string; mimeType?: string; text?: string; blob?: string };
  [key: string]: unknown;
}

export interface AcpToolCallContent {
  type: string;
  content?: AcpContentBlock;
  path?: string;
  oldText?: string | null;
  newText?: string;
  terminalId?: string;
  [key: string]: unknown;
}

export interface AcpToolCall {
  toolCallId: string;
  title?: string;
  name?: string | null;
  kind?: string;
  status?: string;
  content?: AcpToolCallContent[];
  locations?: Array<{ path: string; line?: number | null }>;
  rawInput?: unknown;
  rawOutput?: unknown;
}

export interface AcpPlanEntry {
  content: string;
  priority?: string;
  status?: string;
}

export interface AcpSessionMode {
  id: string;
  name: string;
  description?: string;
}

export interface AcpSessionModeState {
  currentModeId: string;
  availableModes: AcpSessionMode[];
}

export interface AcpConfigSelectOption {
  value: string;
  name: string;
  description?: string;
}

export interface AcpConfigSelectGroup {
  group: string;
  name: string;
  options: AcpConfigSelectOption[];
}

export interface AcpSessionConfigOption {
  id: string;
  name: string;
  description?: string;
  category?: string;
  type: string;
  currentValue: string | boolean;
  options?: Array<AcpConfigSelectOption | AcpConfigSelectGroup>;
}

export interface AcpUsage {
  used: number;
  size: number;
  cost?: { amount: number; currency: string };
}

export interface AcpSessionUpdate {
  sessionUpdate: string;
  content?: AcpContentBlock;
  toolCallId?: string;
  title?: string;
  name?: string | null;
  kind?: string;
  status?: string;
  contentBlocks?: AcpToolCallContent[];
  locations?: Array<{ path: string; line?: number | null }>;
  rawInput?: unknown;
  rawOutput?: unknown;
  entries?: AcpPlanEntry[];
  availableCommands?: Array<{ name: string; description?: string; input?: { hint?: string } | null }>;
  currentModeId?: string;
  modes?: AcpSessionModeState;
  configOptions?: AcpSessionConfigOption[];
  used?: number;
  size?: number;
  cost?: AcpUsage["cost"];
  severity?: string;
  description?: string | null;
  messageId?: string;
  [key: string]: unknown;
}

export interface AcpPermissionOption {
  optionId: string;
  name: string;
  kind: string;
}

export interface AcpElicitationRequest {
  sessionId?: string;
  requestId?: string | number;
  toolCallId?: string | null;
  mode: string;
  message: string;
  requestedSchema?: Record<string, unknown>;
  elicitationId?: string;
  url?: string;
  [key: string]: unknown;
}

export interface AcpClientInput {
  name: string;
  command: string;
  args: string[];
  env: Record<string, string>;
  cwd: string;
  enabled: boolean;
}

export type AcpClientStatus = "disconnected" | "connecting" | "connected" | "error";

export interface AcpClient extends AcpClientInput {
  id: string;
  createdAt: number;
  updatedAt: number;
  status: AcpClientStatus;
  error: string | null;
  agent: AcpImplementation | null;
  protocolVersion: number | null;
  authMethods: AcpAuthMethod[];
  capabilities: AcpAgentCapabilities | null;
  sessions: number;
  stderr: string[];
}

export interface AcpSessionMeta {
  modes?: AcpSessionModeState | null;
  configOptions?: AcpSessionConfigOption[] | null;
  usage?: AcpUsage | null;
  commands?: Array<{ name: string; description?: string; input?: { hint?: string } | null }>;
  agent?: AcpImplementation | null;
  protocolVersion?: number;
  [key: string]: unknown;
}

export interface AcpSession {
  id: string;
  clientId: string;
  title: string;
  status: string;
  running: boolean;
  meta: AcpSessionMeta;
  createdAt: number;
  updatedAt: number;
}

export interface AcpStoredEvent {
  seq: number;
  event: string;
  data: unknown;
  createdAt: number;
}

export interface AcpSessionDetail extends AcpSession {
  events: AcpStoredEvent[];
}

export interface AcpValidateResult {
  ok: boolean;
  agent: AcpImplementation | null;
  protocolVersion: number;
  authMethods: AcpAuthMethod[];
  capabilities: AcpAgentCapabilities | null;
}

export interface AcpClientsPayload {
  clients: AcpClient[];
  workspace: string;
}

export interface AcpClientEvent {
  event: string;
  data: Record<string, unknown>;
}

function str(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function rec(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

function strArray(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

function normalizeClient(raw: unknown): AcpClient {
  const r = rec(raw);
  const env: Record<string, string> = {};
  for (const [key, value] of Object.entries(rec(r.env))) {
    if (typeof value === "string") env[key] = value;
  }
  const status = str(r.status);
  return {
    id: str(r.id),
    name: str(r.name),
    command: str(r.command),
    args: strArray(r.args),
    env,
    cwd: str(r.cwd),
    enabled: r.enabled !== false,
    createdAt: typeof r.createdAt === "number" ? r.createdAt : 0,
    updatedAt: typeof r.updatedAt === "number" ? r.updatedAt : 0,
    status:
      status === "connected" || status === "connecting" || status === "error"
        ? (status as AcpClientStatus)
        : "disconnected",
    error: typeof r.error === "string" ? r.error : null,
    agent: r.agent && typeof r.agent === "object" ? (r.agent as AcpImplementation) : null,
    protocolVersion: typeof r.protocolVersion === "number" ? r.protocolVersion : null,
    authMethods: Array.isArray(r.authMethods) ? (r.authMethods as AcpAuthMethod[]) : [],
    capabilities:
      r.capabilities && typeof r.capabilities === "object"
        ? (r.capabilities as AcpAgentCapabilities)
        : null,
    sessions: typeof r.sessions === "number" ? r.sessions : 0,
    stderr: strArray(r.stderr),
  };
}

function normalizeSession(raw: unknown): AcpSession {
  const r = rec(raw);
  return {
    id: str(r.id),
    clientId: str(r.clientId),
    title: str(r.title),
    status: str(r.status) || "active",
    running: r.running === true,
    meta: rec(r.meta) as AcpSessionMeta,
    createdAt: typeof r.createdAt === "number" ? r.createdAt : 0,
    updatedAt: typeof r.updatedAt === "number" ? r.updatedAt : 0,
  };
}

function normalizeEvent(raw: unknown): AcpStoredEvent {
  const r = rec(raw);
  return {
    seq: typeof r.seq === "number" ? r.seq : 0,
    event: str(r.event),
    data: r.data,
    createdAt: typeof r.createdAt === "number" ? r.createdAt : 0,
  };
}

export async function fetchAcpClients(): Promise<AcpClientsPayload> {
  const data = await requestJson<{ clients?: unknown[]; workspace?: unknown }>(
    routeUrl(API_ROUTES.acpClientList),
  );
  return {
    clients: Array.isArray(data.clients) ? data.clients.map(normalizeClient) : [],
    workspace: str(data.workspace),
  };
}

export async function createAcpClient(input: AcpClientInput): Promise<AcpClient> {
  const data = await requestJson<{ client?: unknown }>(routeUrl(API_ROUTES.acpClientCreate), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(input),
  });
  return normalizeClient(data.client ?? input);
}

export async function updateAcpClient(id: string, input: AcpClientInput): Promise<AcpClient> {
  const data = await requestJson<{ client?: unknown }>(
    routeUrl(API_ROUTES.acpClientUpdate, { params: { id } }),
    {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(input),
    },
  );
  return normalizeClient(data.client ?? input);
}

export async function deleteAcpClient(id: string): Promise<void> {
  await requestJson(routeUrl(API_ROUTES.acpClientDelete, { params: { id } }), { method: "DELETE" });
}

export async function connectAcpClient(id: string): Promise<AcpClient> {
  const data = await requestJson<{ client?: unknown }>(
    routeUrl(API_ROUTES.acpClientConnect, { params: { id } }),
    { method: "POST" },
  );
  return normalizeClient(data.client);
}

export async function disconnectAcpClient(id: string): Promise<AcpClient> {
  const data = await requestJson<{ client?: unknown }>(
    routeUrl(API_ROUTES.acpClientDisconnect, { params: { id } }),
    { method: "POST" },
  );
  return normalizeClient(data.client);
}

export async function validateAcpClient(input: AcpClientInput): Promise<AcpValidateResult> {
  const data = await requestJson<AcpValidateResult>(routeUrl(API_ROUTES.acpClientValidate), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(input),
  });
  return {
    ok: data.ok === true,
    agent: data.agent ?? null,
    protocolVersion: typeof data.protocolVersion === "number" ? data.protocolVersion : 1,
    authMethods: Array.isArray(data.authMethods) ? data.authMethods : [],
    capabilities: data.capabilities ?? null,
  };
}

