/** Open the prompt SSE stream. Throws on non-2xx with the backend's message. */
export async function openAcpPrompt(
  clientId: string,
  sessionId: string,
  text: string,
  signal: AbortSignal,
): Promise<Response> {
  const res = await fetch(
    routeUrl(API_ROUTES.acpClientSessionPrompt, { params: { id: clientId, sessionId } }),
    {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "text/event-stream" },
      body: JSON.stringify({ text }),
      cache: "no-store",
      signal,
    },
  );
  if (!res.ok) {
    const data = (await res.json().catch(() => ({}))) as { error?: string };
    throw new Error(data.error ?? `Request failed (${res.status})`);
  }
  return res;
}

/** Parse an ACP prompt SSE stream into generic `{ event, data }` callbacks. */
export async function parseAcpSse(
  res: Response,
  onEvent: (event: string, data: Record<string, unknown>) => void,
  signal: AbortSignal,
): Promise<void> {
  if (!res.body) return;
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  const cancel = () => {
    reader.cancel().catch(() => {});
  };
  signal.addEventListener("abort", cancel, { once: true });
  try {
    for (;;) {
      if (signal.aborted) return;
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      buffer = buffer.replace(/\r\n/g, "\n");
      let sep: number;
      while ((sep = buffer.indexOf("\n\n")) !== -1) {
        const raw = buffer.slice(0, sep);
        buffer = buffer.slice(sep + 2);
        let event = "message";
        const dataLines: string[] = [];
        for (const line of raw.split("\n")) {
          if (line.startsWith("event:")) event = line.slice(6).trim();
          else if (line.startsWith("data:")) dataLines.push(line.slice(5).trim());
        }
        if (dataLines.length === 0) continue;
        try {
          const parsed = JSON.parse(dataLines.join("\n")) as unknown;
          onEvent(event, rec(parsed));
        } catch {
          // ignore malformed frame
        }
      }
    }
  } finally {
    signal.removeEventListener("abort", cancel);
  }
}